import{_ as i,l as o,o as e,c as n,v as t,p as s,x as r,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"椭圆曲线群","description":"","frontmatter":{"title":"椭圆曲线群","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/elliptic-curve-group.md","filePath":"cs/elliptic-curve-group.md","lastUpdated":1789023840000}'),c={name:"cs/elliptic-curve-group.md"};function m(_,a,u,E,P,b){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="椭圆曲线群" tabindex="-1">椭圆曲线群 <a class="header-anchor" href="#椭圆曲线群" aria-label="Permalink to &quot;椭圆曲线群&quot;">​</a></h1><div class="epigraph"><p>域上非奇异三次曲线的点，加上无穷远点，用割线–切线定义加法，构成 Abel 群；DLP 在此群上目前比 $\\mathbb{F}_p$ 更硬，故密钥更短。</p><footer>—— 据 Silverman, The Arithmetic of Elliptic Curves；Hankerson, Menezes and Vanstone 整理</footer></div><p>上一课<a href="/cs/prime-generation">素数生成</a> 给出 \\(\\mathbb{F}_p\\)。缺口是 <strong>ECC 群</strong>：点集 \\(E(\\mathbb{F}_q)\\)，\\(\\mathcal{O}\\) 为单位，弦切法为加。本课直觉与阶，不写 TLS 曲线清单。主干 DH 的报文形状可原样搬到 \\(P\\mapsto [k]P\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>仿射方程 \\(y^2=x^3+Ax+B\\)（特征 \\(\\ne 2,3\\)），判别式非零。两点连线交第三点，再对 \\(x\\) 轴反射，定义为和。切线处理倍点。\\(\\mathcal{O}\\) 是竖直线的「无穷」。结合律不显然，本课承认。Hasse：\\(|\\#E-(q+1)|\\le 2\\sqrt q\\)。选阶为大素，或大素子群，防 Pohlig–Hellman。</p><p>标量乘 \\([k]P\\) 用倍加，对标快速幂。DLP：已知 \\(P,[k]P\\) 求 \\(k\\)。无通用指标演算，故 256 比特曲线对标 3072 比特有限域（NIST 量级，点名）。</p><h3 id="不是圆锥曲线插值" tabindex="-1">不是圆锥曲线插值 <a class="header-anchor" href="#不是圆锥曲线插值" aria-label="Permalink to &quot;不是圆锥曲线插值&quot;">​</a></h3><p>「椭圆」来自椭圆积分，不是椭圆形状。与率失真、编码无关。</p><p><span class="marginnote">Silverman 算术。HMV 密码学椭圆曲线。Miller 的 pairing 点名不写。扭曲线、异常曲线是不安全族，选曲线要避开，本课不列 CVE。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在小素域上画几个点，演示 \\(P+(-P)=\\mathcal{O}\\)。对照 \\(\\mathbb{F}_p^\\times\\)：运算换成点加，困难问题仍是 DLP。指出：生成元是基点 \\(G\\)，公开参数含曲线与 \\(G\\)、阶 \\(n\\)。</p>',11)),(e(),s(d,null,{default:r(()=>[h(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CRV%5B%22%E4%B8%89%E6%AC%A1%E6%9B%B2%E7%BA%BF%20E%22%5D%20--%3E%20PTS%5B%22%E7%82%B9%20%2B%20O%22%5D%0A%20%20PTS%20--%3E%20ADD%5B%22%E5%BC%A6%E5%88%87%E5%8A%A0%E6%B3%95%22%5D%0A%20%20ADD%20--%3E%20DLP%5B%22%E6%A0%87%E9%87%8F%E4%B9%98%E6%98%93%20%2F%20DLP%20%E9%9A%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>ECC 把 DH、ECDSA 的群换掉，不改协议逻辑。量子 Shor 对 ECC DLP 同样有效（BQP 课）。后量子不在这条曲线上找，下一课格。本课是经典公钥群的最后一站。</p><p>实现：常数时间标量乘、点压缩，属工程，点名。</p><p>点加公式：斜率 \\(\\lambda=(y_2-y_1)/(x_2-x_1)\\) 或切线 \\((3x^2+A)/2y\\)，再 \\(x_3=\\lambda^2-x_1-x_2\\)。无穷远是单位。扭曲、小判别式、非素阶会掉进 Pohlig–Hellman 或 MOV 转移，选曲线要按标准。Shor 对 \\([k]P\\) 同样多项式，后量子不在 ECC 上续命。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证结合律，不引入除子、Weil 对。不选具体 NIST/Curve25519 当定义。后课默认：ECC 群是弦切 Abel 群，DLP 假设更强于大素数域。下一课格与 LWE。</p><p>弦切法给出 Abel 群，标量乘是快速幂。Hasse 管点数，阶要有大素因子。协议形状与 DH 相同，密钥更短。Shor 同样适用，故后量子不在这条曲线上找。</p><p>上一课留下的缺口在本课收口；「椭圆曲线群」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(E(\\mathbb{F}_q)\\) 弦切成 Abel 群；标量乘 = 快速幂。</li><li>Hasse 管点数；阶要有大素因子。</li><li>同形 DH，更短密钥；Shor 仍威胁。</li><li>出处：Silverman；Hankerson, Menezes and Vanstone。</li></ul>',10))])}const D=i(c,[["render",m]]);export{C as __pageData,D as default};
